"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["18002"],{89473(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.calendario_dias_uteis_congelado.versao_do_calendario_obrigatoria","status":422,"titulo":"Vers\xe3o do calend\xe1rio \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.selecao.calendario_dias_uteis_congelado.versao_do_calendario_obrigatoria","requisitos":["UNI-REQ-0080"],"oQueAconteceu":["O calend\xe1rio de dias \xfateis vigente chegou sem a vers\xe3o do calend\xe1rio de origem, ou com a vers\xe3o em\\nbranco. A vers\xe3o congelada guarda, ao lado da lista de dias n\xe3o \xfateis, o identificador e a vers\xe3o do\\ncalend\xe1rio de onde ela veio, s\xf3 como rastreio.","O calend\xe1rio de dias \xfateis vigente \xe9 cadastrado no m\xf3dulo Configura\xe7\xe3o, e a vers\xe3o do processo\\ncongela uma c\xf3pia dele por valor, com a lista dos dias n\xe3o \xfateis (UNI-REQ-0080). Ao copi\xe1-lo, o\\nsistema confere de novo cada dia e o conjunto, e recusa o que o cadastro n\xe3o aceitaria. A recusa\\ns\xf3 vale para o processo que depende do calend\xe1rio, isto \xe9, o que tem prazo de recurso (ver\\n[calend\xe1rio vigente ausente](/erros/uniplus.selecao.processo_seletivo.calendario_vigente_ausente)); um processo sem contagem sobre dia \xfatil segue normalmente, porque n\xe3o usa o dado.","A confer\xeancia vem depois das da localidade ([`localidade_ausente`](/erros/uniplus.selecao.processo_seletivo.localidade_ausente)) e da conven\xe7\xe3o de contagem\\n([`algoritmo_contagem_prazo_nao_declarado`](/erros/uniplus.selecao.processo_seletivo.algoritmo_contagem_prazo_nao_declarado)), e antes das demais confer\xeancias de conformidade e do cronograma. A consulta de\\nconformidade do processo mostra o item \\"Calend\xe1rio de dias \xfateis vigente\\" como pendente enquanto o\\ncalend\xe1rio vigente estiver nessa condi\xe7\xe3o. Nada \xe9 gravado.","Os dias s\xe3o conferidos um a um, na ordem em que o calend\xe1rio os lista, e o primeiro dia com\\ndefeito interrompe a c\xf3pia. As confer\xeancias do calend\xe1rio como um todo (identificador, vers\xe3o,\\nlista vazia e dia repetido) v\xeam depois das de todos os dias. Esta confer\xeancia vem depois da do identificador\\n([`origem_obrigatoria`](/erros/uniplus.selecao.calendario_dias_uteis_congelado.origem_obrigatoria)) e antes da do\\ntamanho da vers\xe3o ([`versao_do_calendario_tamanho`](/erros/uniplus.selecao.calendario_dias_uteis_congelado.versao_do_calendario_tamanho))."],"comoResolver":["A causa n\xe3o est\xe1 na configura\xe7\xe3o do processo, e nada nela corrige a recusa: o dado vem do\\ncalend\xe1rio de dias \xfateis vigente, cadastrado no m\xf3dulo Configura\xe7\xe3o. Como a vers\xe3o publicada\\ncongela o calend\xe1rio por valor, a corre\xe7\xe3o \xe9 na origem, antes de publicar ou retificar:\\ncadastre um calend\xe1rio corrigido, que o cadastro confere ao criar, coloque-o em vig\xeancia\\ne repita a opera\xe7\xe3o.","O cadastro exige a vers\xe3o ao criar o calend\xe1rio ([`versao_do_calendario_obrigatoria`](/erros/uniplus.configuracao.calendario_dias_uteis.versao_do_calendario_obrigatoria)). Um calend\xe1rio\\nvigente nessa condi\xe7\xe3o indica dado gravado por caminho que n\xe3o passou por essa confer\xeancia, e a\\ncausa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Calendario dias uteis congelado"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);